44	/// Minimum spacing between accepted status polls for one request; a faster poll gets the
45	/// `slow_down` 429 the page's JS backs off on (the `claim_polling` discipline).
46	const STATUS_POLL_MIN_INTERVAL: Duration = Duration::from_secs(2);
47	
