50	/// A request that is no longer approvable — absent, terminal, or lapsed — maps to one uniform
51	/// response so the caller can't probe request state beyond "pending or not".
52	fn not_approvable() -> ApiError {
53	    ApiError::new(
54	        ErrorCode::NotFound,
55	        "authorization request not found or expired",
56	    )
57	}
58	
59	/// Signature / authority / binding failures share one message so the surface reveals nothing about
60	/// which check failed.
61	fn approval_rejected() -> ApiError {
62	    ApiError::new(
63	        ErrorCode::AuthenticationRequired,
64	        "consent approval rejected",
65	    )
66	}
