68	/// Reduce the wallet's requested granted-scope string to the tokens actually on offer: `atproto` is
69	/// always granted (never optional), and every other token is kept only if it was part of the
70	/// request's snapshotted `requested_scope`. This mirrors `oauth_authorize`'s reduction filter, so a
71	/// tampered/injected token that was never requested cannot add scope — only narrow it.
72	fn reduce_granted_scope(requested_scope: &str, wallet_granted: &str) -> String {
73	    let wallet: Vec<&str> = wallet_granted.split_whitespace().collect();
74	    requested_scope
75	        .split_whitespace()
76	        .filter(|t| *t == "atproto" || wallet.contains(t))
77	        .collect::<Vec<_>>()
78	        .join(" ")
79	}
