104	/// `GET /oauth/authorize/consent-request` — the wallet's preview of a pending request, resolved by
105	/// `user_code` (typed) or `request_id` (handoff). Returns 404 for anything not currently pending so
106	/// a guessed code reveals nothing.
107	pub async fn get_consent_request(
108	    State(state): State<AppState>,
109	    Query(query): Query<ConsentRequestQuery>,
110	) -> Result<Json<ConsentRequestPreview>, ApiError> {
111	    let pending = match (&query.user_code, &query.request_id) {
112	        (Some(code), None) => get_pending_by_user_code(&state.db, code).await?,
113	        (None, Some(request_id)) => get_pending_by_request_id(&state.db, request_id).await?,
114	        _ => {
115	            return Err(ApiError::new(
116	                ErrorCode::InvalidRequest,
117	                "exactly one of userCode or requestId is required",
118	            ))
119	        }
120	    };
121	    let pending = pending.filter(|p| p.status == "pending" && !p.is_expired);
122	    let Some(p) = pending else {
123	        return Err(not_approvable());
124	    };
125	    Ok(Json(ConsentRequestPreview {
126	        request_id: p.request_id,
127	        client_id: p.client_id,
128	        client_name: p.client_name,
129	        redirect_uri: p.redirect_uri,
130	        origin: p.origin,
131	        ip: p.ip,
132	        requested_scope: p
133	            .requested_scope
134	            .split_whitespace()
135	            .map(str::to_string)
136	            .collect(),
137	        login_hint: p.login_hint,
138	    }))
139	}
