153	/// `GET /oauth/authorize/status?request_id=…` — the consent page's poll. Throttled per request with
154	/// the `slow_down` discipline (429 when polled faster than `STATUS_POLL_MIN_INTERVAL`), and reports
155	/// a derived `expired` for a lapsed or reclaimed request so the page stops.
156	pub async fn get_authorization_status(
157	    State(state): State<AppState>,
158	    Query(query): Query<StatusQuery>,
159	) -> Response {
160	    // slow_down throttle, reusing the shared poll tracker with a namespaced key so it can't collide
161	    // with agent claim-poll marks. A poll faster than the interval gets a 429 the page backs off on.
162	    {
163	        let key = format!("consent:{}", query.request_id);
164	        let mut tracker = state.poll_tracker.lock().unwrap_or_else(|e| e.into_inner());
165	        if let Some(last) = tracker.get(&key) {
166	            if last.elapsed() < STATUS_POLL_MIN_INTERVAL {
167	                return (
168	                    StatusCode::TOO_MANY_REQUESTS,
169	                    Json(StatusResponse {
170	                        status: "slow_down",
171	                    }),
172	                )
173	                    .into_response();
174	            }
175	        }
176	        tracker.insert(key, Instant::now());
177	    }
178	
179	    let pending = match get_pending_by_request_id(&state.db, &query.request_id).await {
180	        Ok(p) => p,
181	        Err(e) => return e.into_response(),
182	    };
183	    let status = match pending {
184	        // Absent (never created or reclaimed) reads as expired so the page stops polling.
185	        None => "expired",
186	        Some(p) if p.status == "pending" && p.is_expired => "expired",
187	        Some(p) => match p.status.as_str() {
188	            "pending" => "pending",
189	            "approved" => "approved",
190	            "denied" => "denied",
191	            "completed" => "completed",
192	            _ => "expired",
193	        },
194	    };
195	    Json(StatusResponse { status }).into_response()
196	}
