219	pub struct ApprovalResponse {
220	    status: &'static str,
221	    did: String,
222	}
223	
224	/// Whether a client-supplied `login_hint` denotes the approving account.
225	///
226	/// The hint is whatever the client forwarded from the user and is entirely unverified. An atproto
227	/// client sends the handle the user typed far more often than a DID, so this is deliberately not a
228	/// string comparison against `did` — that comparison rejected every honest sign-in whose client
229	/// passed a handle.
230	///
231	/// A handle binds only when **both** halves of the atproto bidirectional rule hold: the account's
232	/// authoritative state asserts it in `alsoKnownAs`, and the handle resolves back to this DID.
233	/// Assertion alone is the account's own claim — `alsoKnownAs` is writable by whoever controls the
234	/// DID, so any account could otherwise claim any handle and approve a request named for someone
235	/// else. `authority` carries that assertion read from the same authoritative source as the signing
236	/// keys, never the `did_documents` cache (which a Custos-hosted did:web account can rewrite under
237	/// session auth).
238	///
239	/// A hint that does not denote this account is `Ok(false)`, including a structurally invalid one —
240	/// `Err` stays reserved for a lookup the server could not complete at all, so an internal failure
241	/// keeps its own status instead of reading as a rejected approval. Note that a DNS/well-known
242	/// outage resolves to `Ok(None)` rather than an error, so a user-domain handle is refused while its
243	/// resolution is down; entering the DID still binds, since that path performs no resolution.
244	async fn hint_binds_account(
245	    state: &AppState,
246	    hint: &str,
247	    did: &str,
248	    authority: &AuthoritySet,
249	) -> Result<bool, ApiError> {
250	    if hint.starts_with("did:") {
251	        return Ok(hint == did);
252	    }
253	
254	    let handle = hint.strip_prefix("at://").unwrap_or(hint);
255	    let handle = handle
256	        .strip_prefix('@')
257	        .unwrap_or(handle)
258	        .to_ascii_lowercase();
259	
260	    if crate::identity::handle::validate_handle_structure(&handle).is_err() {
261	        return Ok(false);
262	    }
263	    if !authority.asserts_handle(&handle) {
264	        return Ok(false);
265	    }
266	    Ok(resolve_handle_to_did(state, &handle).await?.as_deref() == Some(did))
267	}
