269	/// `POST /oauth/authorize/approve` — verify a device-key-signed approve/deny envelope against the
270	/// account's authoritative current signing authority and terminate the request accordingly.
271	pub async fn post_authorization_approve(
272	    State(state): State<AppState>,
273	    Json(request): Json<ApprovalRequest>,
274	) -> Result<Json<ApprovalResponse>, ApiError> {
275	    // 1. Cheap syntactic gates before any DB or network work.
276	    let signature = decode_canonical_base64url(&request.signature, SIGNATURE_BYTES)
277	        .and_then(|bytes| <[u8; SIGNATURE_BYTES]>::try_from(bytes).ok())
278	        .ok_or_else(approval_rejected)?;
279	    if decode_canonical_base64url(&request.nonce, NONCE_BYTES).is_none() {
280	        return Err(approval_rejected());
281	    }
282	    let approve = match request.decision.as_str() {
283	        crypto::OAUTH_CONSENT_DECISION_APPROVE => true,
284	        crypto::OAUTH_CONSENT_DECISION_DENY => false,
285	        _ => return Err(approval_rejected()),
286	    };
287	    let now = crate::time::unix_now_secs();
288	    if now.abs_diff(request.timestamp) > SOVEREIGN_TIMESTAMP_WINDOW_SECS as u64 {
289	        return Err(approval_rejected());
290	    }
291	
292	    // 2. Load the pending request; it must be currently approvable.
293	    let pending = get_pending_by_request_id(&state.db, &request.request_id)
294	        .await?
295	        .filter(|p| p.status == "pending" && !p.is_expired)
296	        .ok_or_else(not_approvable)?;
297	
298	    // 3. The approving DID must be a local active account so the authorization code can be issued
299	    //    against it. Any `login_hint` binding is deferred to step 6, which needs the authoritative
300	    //    state step 5 fetches.
301	    if !crate::db::accounts::active_local_account_exists(&state.db, &request.did).await? {
302	        return Err(approval_rejected());
303	    }
304	
305	    // 4. The granted scope the wallet signed over is the verbatim `granted_scope` string (empty for
306	    //    a denial); the stored set is that, reduced to what was actually requested.
307	    let signed_scope = if approve {
308	        request.granted_scope.as_str()
309	    } else {
310	        ""
311	    };
312	    let stored_scope = reduce_granted_scope(&pending.requested_scope, signed_scope);
313	
314	    // 5. Verify the envelope signature, then confirm the signing key is in the account's
315	    //    authoritative current signing authority (never the cached DID doc). Signature first, so an
316	    //    invalid signature never triggers the outbound authority lookup.
317	    let server_did = state.config.resolve_server_did();
318	    let envelope = crypto::encode_oauth_consent_envelope(
319	        &server_did,
320	        &request.did,
321	        &request.signing_key,
322	        &request.request_id,
323	        &pending.client_id,
324	        &request.decision,
325	        signed_scope,
326	        request.timestamp,
327	        &request.nonce,
328	    );
329	    let signing_key = crypto::DidKeyUri(request.signing_key.clone());
330	    crypto::verify_did_key_signature(&signing_key, &envelope, &signature)
331	        .map_err(|_| approval_rejected())?;
332	
333	    let authority = authorized_signing_keys(&state, &request.did)
334	        .await
335	        .map_err(|error| match error {
336	            AuthorityError::Unauthorized(_) => approval_rejected(),
337	            AuthorityError::Lookup(err) => err,
338	        })?;
339	    if !authority.authorizes(&request.signing_key) {
340	        return Err(approval_rejected());
341	    }
342	
343	    // 6. Account binding: a `login_hint` pre-names the account the client expects to approve, so an
344	    //    approval by anyone else is refused. It is bound here rather than up front because the hint
345	    //    is usually a handle, and resolving one belongs against the same authoritative state step 5
346	    //    just read — and sitting behind `authorizes` means only a genuine key holder can drive the
347	    //    outbound handle resolution it may perform.
348	    if let Some(hint) = pending.login_hint.as_deref() {
349	        if !hint_binds_account(&state, hint, &request.did, &authority).await? {
350	            return Err(approval_rejected());
351	        }
352	    }
353	
354	    // 7. Terminate the request and audit it in one transaction. The guarded UPDATE is the single-use
355	    //    point: a replayed envelope lands on an already-terminal row and wins nothing.
356	    let mut tx = state.db.begin().await.map_err(|e| {
357	        tracing::error!(error = %e, "failed to begin consent approval transaction");
358	        ApiError::new(ErrorCode::InternalError, "failed to record decision")
359	    })?;
360	    let won = if approve {
361	        approve_pending_authorization(&mut *tx, &request.request_id, &request.did, &stored_scope)
362	            .await?
363	    } else {
364	        deny_pending_authorization(&mut *tx, &request.request_id, &request.did).await?
365	    };
366	    if !won {
367	        return Err(ApiError::new(
368	            ErrorCode::InvalidRequest,
369	            "authorization request already resolved",
370	        ));
371	    }
372	    let (event, detail) = if approve {
373	        (
374	            OAuthConsentAuditEventType::Approved,
375	            serde_json::json!({ "granted_scope": stored_scope }).to_string(),
376	        )
377	    } else {
378	        (
379	            OAuthConsentAuditEventType::Denied,
380	            serde_json::json!({}).to_string(),
381	        )
382	    };
383	    insert_oauth_consent_audit_event(
384	        &mut *tx,
385	        &uuid::Uuid::new_v4().to_string(),
386	        &request.request_id,
387	        Some(&request.did),
388	        &pending.client_id,
389	        event,
390	        Some(&detail),
391	    )
392	    .await?;
393	    tx.commit().await.map_err(|e| {
394	        tracing::error!(error = %e, "failed to commit consent approval transaction");
395	        ApiError::new(ErrorCode::InternalError, "failed to record decision")
396	    })?;
397	
398	    tracing::info!(
399	        account_did = %request.did,
400	        client_id = %pending.client_id,
401	        decision = %request.decision,
402	        authority = %authority.source,
403	        "wallet-confirmed OAuth consent decision recorded"
404	    );
405	    Ok(Json(ApprovalResponse {
406	        status: if approve { "approved" } else { "denied" },
407	        did: request.did,
408	    }))
409	}
