418	/// `POST /oauth/authorize/complete` — the browser exchanges an approved request for an
419	/// authorization code and is redirected back to the client. The guarded `approved → completed`
420	/// transition mints at most one code; a no-JS "I've approved — continue" button and the page's JS
421	/// poller both post here.
422	pub async fn post_authorization_complete(
423	    State(state): State<AppState>,
424	    Form(form): Form<CompleteForm>,
425	) -> Response {
426	    let issuer = state.config.public_url.trim_end_matches('/').to_string();
427	
428	    // The guarded transition, authorization-code insert, and completion audit share one transaction:
429	    // a failed code insert rolls the `approved → completed` transition back, so the request stays
430	    // retryable instead of being consumed with no code ever issued.
431	    let token = generate_token();
432	    let mut tx = match state.db.begin().await {
433	        Ok(tx) => tx,
434	        Err(e) => {
435	            tracing::error!(error = %e, "failed to begin consent completion transaction");
436	            return error_page(
437	                "Server Error",
438	                "Failed to issue the authorization code. Please try again.",
439	            )
440	            .into_response();
441	        }
442	    };
443	
444	    let completed = match complete_pending_authorization(&mut *tx, &form.request_id).await {
445	        Ok(Some(c)) => c,
446	        Ok(None) => {
447	            // Not in `approved` state: still pending, denied, expired, or already completed.
448	            return error_page(
449	                "Not Ready",
450	                "This authorization request has not been approved yet, or has already been used. \
451	                 Return to the app and start again if needed.",
452	            )
453	            .into_response();
454	        }
455	        Err(e) => return e.into_response(),
456	    };
457	
458	    if let Err(e) = store_authorization_code(
459	        &mut *tx,
460	        &token.hash,
461	        &completed.client_id,
462	        &completed.account_did,
463	        &completed.code_challenge,
464	        &completed.code_challenge_method,
465	        &completed.redirect_uri,
466	        &completed.granted_scope,
467	    )
468	    .await
469	    {
470	        tracing::error!(error = %e, "failed to store authorization code for wallet consent");
471	        return error_page(
472	            "Server Error",
473	            "Failed to issue the authorization code. Please try again.",
474	        )
475	        .into_response();
476	    }
477	
478	    if let Err(e) = insert_oauth_consent_audit_event(
479	        &mut *tx,
480	        &uuid::Uuid::new_v4().to_string(),
481	        &form.request_id,
482	        Some(&completed.account_did),
483	        &completed.client_id,
484	        OAuthConsentAuditEventType::Completed,
485	        Some(&serde_json::json!({ "granted_scope": completed.granted_scope }).to_string()),
486	    )
487	    .await
488	    {
489	        return e.into_response();
490	    }
491	
492	    if let Err(e) = tx.commit().await {
493	        tracing::error!(error = %e, "failed to commit consent completion transaction");
494	        return error_page(
495	            "Server Error",
496	            "Failed to issue the authorization code. Please try again.",
497	        )
498	        .into_response();
499	    }
500	
501	    // Answer in the response mode the client asked for at PAR/authorize time (carried on
502	    // the pending row) — a fragment-mode browser client only ever reads `location.hash`.
503	    // The stored value was validated before it was written, so an unparseable one means
504	    // row tampering/drift; falling back to `query` (the protocol default) is the honest
505	    // degraded answer rather than a hard failure after consent already happened.
506	    let mode =
507	        crate::auth::oauth_response_mode::ResponseMode::parse(Some(&completed.response_mode))
508	            .unwrap_or(crate::auth::oauth_response_mode::ResponseMode::Query);
509	    build_code_redirect(
510	        &completed.redirect_uri,
511	        &token.plaintext,
512	        &completed.state,
513	        &issuer,
514	        mode,
515	    )
516	    .into_response()
517	}
