121	async fn fan_out(
122	    state: &AppState,
123	    sender: &crate::notify_relay_client::NotifySender,
124	    registrations: Vec<store::RegistrationRow>,
125	    payload: NotificationPayload,
126	    owner_of: impl Fn(String) -> RegistrationOwner,
127	) {
128	    if registrations.is_empty() {
129	        return;
130	    }
131	
132	    // Load the sealing key once for the whole fan-out. Doing it per device would mean a
133	    // rotation landing mid-fan-out seals some devices under the old key and some under the
134	    // new — both valid, but needlessly hard to reason about when debugging a delivery.
135	    let Some((kid, secret)) = active_sender_key(state).await else {
136	        return;
137	    };
138	
139	    for registration in registrations {
140	        // A registration with no handle has not completed its relay round trip yet (the
141	        // relay was down at registration time, or the job is still queued). There is nothing
142	        // to push to; the next registration attempt mints one.
143	        let Some(handle) = registration.push_handle.clone() else {
144	            continue;
145	        };
146	
147	        let recipient =
148	            match crypto::p256_public_key_from_did_key(&registration.notification_public_key) {
149	                Ok(key) => key,
150	                Err(e) => {
151	                    // Registration validated this key, so reaching here means the stored row is
152	                    // corrupt — worth an error, not a silent skip.
153	                    tracing::error!(error = %e, "stored notification public key is unusable");
154	                    continue;
155	                }
156	            };
157	
158	        let Some(sealed) = seal_for(kid, &secret, &recipient, &payload) else {
159	            continue;
160	        };
161	
162	        // `send` fails only once every receiver is gone, i.e. the worker has stopped. Not
163	        // worth a per-device log line.
164	        sender.send(NotifyJob::Push {
165	            owner: owner_of(registration.device_id),
166	            handle,
167	            kid,
168	            enc: base64url(&sealed.enc),
169	            ct: base64url(&sealed.ct),
170	        });
171	    }
172	}
