174	/// Pad, then seal, one payload for one recipient.
175	///
176	/// Returns `None` when the payload cannot be sent — which for v1 means only one thing: it is
177	/// too large for the top padding bucket. We refuse rather than degrade. Sending it unpadded
178	/// would leak the exact length that padding exists to hide, and truncating the body would
179	/// deliver a security notice that no longer says what happened; a dropped banner is the one
180	/// failure mode with no downside beyond the missed banner itself.
181	fn seal_for(
182	    kid: i64,
183	    sender_secret: &[u8; 32],
184	    recipient_public_key: &[u8],
185	    payload: &NotificationPayload,
186	) -> Option<crypto::SealedNotification> {
187	    let pad_len = pad_len_for(kid, payload)?;
188	
189	    let mut padded = payload.clone();
190	    padded.pad = " ".repeat(pad_len);
191	    let plaintext = match serde_json::to_vec(&padded) {
192	        Ok(bytes) => bytes,
193	        Err(e) => {
194	            tracing::error!(error = %e, "failed to serialize a notification payload");
195	            return None;
196	        }
197	    };
198	
199	    match crypto::seal_notification(sender_secret, recipient_public_key, &plaintext) {
200	        Ok(sealed) => Some(sealed),
201	        Err(e) => {
202	            tracing::error!(error = %e, "failed to seal a notification");
203	            None
204	        }
205	    }
206	}
207	
208	/// How many pad bytes make this payload's APNs body land on a bucket.
209	///
210	/// The buckets are defined on the **serialized APNs request body**, because that is the only
211	/// length anyone on the path actually measures. So this models the exact body the relay will
212	/// build (via the shared [`notify_relay::protocol::apns_envelope`]) and works backwards
213	/// through base64url expansion. Sealing is deterministic in length — ciphertext is plaintext
214	/// plus a 16-byte tag, and `enc` is always a 65-byte point — so this needs no trial seal.
215	fn pad_len_for(kid: i64, payload: &NotificationPayload) -> Option<usize> {
216	    let unpadded_plaintext_len = serde_json::to_vec(payload).ok()?.len();
217	    let unpadded_ct_len = unpadded_plaintext_len + AEAD_TAG_LEN;
218	
219	    // Placeholder strings of the right *length*: only the byte count reaches the arithmetic,
220	    // and JSON escaping never touches base64url's alphabet.
221	    let envelope = notify_relay::protocol::apns_envelope(
222	        kid as u32,
223	        &"A".repeat(crypto::base64url_len(P256_POINT_LEN)),
224	        &"A".repeat(crypto::base64url_len(unpadded_ct_len)),
225	    );
226	    let unpadded_serialized_len = serde_json::to_vec(&envelope).ok()?.len();
227	
228	    let pad = crypto::plaintext_pad_len(unpadded_ct_len, unpadded_serialized_len);
229	    if pad.is_none() {
230	        tracing::error!(
231	            serialized_len = unpadded_serialized_len,
232	            "refusing to send a notification too large for any padding bucket; \
233	             sending it unpadded would leak the length padding exists to hide"
234	        );
235	    }
236	    pad
237	}
