175	/// Shared preview core. `query_key` selects the server's lookup dimension (`user_code` for the typed
176	/// path, `request_id` for the scan/handoff path); the server resolves the same pending request and
177	/// returns the identical `ConsentRequestPreview` either way, so the wallet screen is unchanged.
178	pub(crate) async fn preview_oauth_consent_impl(
179	    pds_client: &PdsClient,
180	    did: impl AsRef<str>,
181	    query_key: &str,
182	    query_value: impl AsRef<str>,
183	) -> Result<ConsentPreview, ConsentError> {
184	    let did = did.as_ref();
185	    let pds_url = resolve_safe_pds(pds_client, did).await?;
186	    let url = format!(
187	        "{}/oauth/authorize/consent-request?{}={}",
188	        pds_url.trim_end_matches('/'),
189	        query_key,
190	        urlencoding::encode(query_value.as_ref())
191	    );
192	    let response =
193	        pds_client
194	            .client()
195	            .get(url)
196	            .send()
197	            .await
198	            .map_err(|e| ConsentError::TransportFailure {
199	                message: e.to_string(),
200	            })?;
201	    let status = response.status();
202	    if !status.is_success() {
203	        return Err(match status.as_u16() {
204	            404 => ConsentError::RequestNotFound,
205	            405 => ConsentError::UnsupportedHost,
206	            429 => ConsentError::RateLimited {
207	                retry_after: response
208	                    .headers()
209	                    .get(reqwest::header::RETRY_AFTER)
210	                    .and_then(|value| value.to_str().ok())
211	                    .map(str::to_string),
212	            },
213	            status => ConsentError::ServerFailure { status },
214	        });
215	    }
216	    response
217	        .json::<ConsentPreview>()
218	        .await
219	        .map_err(|e| ConsentError::InvalidResponse {
220	            message: e.to_string(),
221	        })
222	}
