224	/// Sign and submit a decision (approve/deny) for a previewed authorization. `granted_scope` is the
225	/// space-joined scope set the wallet chose (empty for a denial). The signed envelope binds the
226	/// `request_id`, `client_id`, decision, and granted-scope hash to the account's device key.
227	#[tauri::command]
228	pub async fn confirm_oauth_consent(
229	    state: tauri::State<'_, AppState>,
230	    did: String,
231	    request_id: String,
232	    client_id: String,
233	    decision: String,
234	    granted_scope: String,
235	) -> Result<ConsentDecision, ConsentError> {
236	    let nonce = fresh_nonce();
237	    let timestamp = unix_timestamp().map_err(|_| ConsentError::InvalidResponse {
238	        message: "system clock is before Unix epoch".into(),
239	    })?;
240	    confirm_oauth_consent_impl(
241	        state.pds_client(),
242	        &IdentityStore,
243	        &did,
244	        &request_id,
245	        &client_id,
246	        &decision,
247	        &granted_scope,
248	        timestamp,
249	        &nonce,
250	    )
251	    .await
252	}
