254	#[allow(clippy::too_many_arguments)]
255	pub(crate) async fn confirm_oauth_consent_impl(
256	    pds_client: &PdsClient,
257	    store: &IdentityStore,
258	    did: &str,
259	    request_id: &str,
260	    client_id: &str,
261	    decision: &str,
262	    granted_scope: &str,
263	    timestamp: i64,
264	    nonce: &str,
265	) -> Result<ConsentDecision, ConsentError> {
266	    if decision != crypto::OAUTH_CONSENT_DECISION_APPROVE
267	        && decision != crypto::OAUTH_CONSENT_DECISION_DENY
268	    {
269	        return Err(ConsentError::InvalidResponse {
270	            message: "decision must be approve or deny".into(),
271	        });
272	    }
273	
274	    // Resolve the signing key before any request — enforces managed-DID membership and guarantees
275	    // the selected DID's device key is the signer.
276	    let device_key = store
277	        .get_or_create_device_key(did)
278	        .map_err(map_store_error)?;
279	    let signer = crate::identity_store::per_did_sign_closure(did).map_err(|error| match error {
280	        PerDidSignError::DeviceKeyNotFound { message }
281	        | PerDidSignError::SigningSetupFailed { message } => {
282	            ConsentError::SigningFailed { message }
283	        }
284	    })?;
285	
286	    let pds_url = resolve_safe_pds(pds_client, did).await?;
287	    let server = pds_client
288	        .describe_server(&pds_url)
289	        .await
290	        .map_err(map_discovery_error)?;
291	    if !server.did.starts_with("did:") || server.did.chars().any(char::is_whitespace) {
292	        return Err(ConsentError::ServerMismatch);
293	    }
294	
295	    let envelope = crypto::encode_oauth_consent_envelope(
296	        &server.did,
297	        did,
298	        &device_key.key_id,
299	        request_id,
300	        client_id,
301	        decision,
302	        granted_scope,
303	        timestamp,
304	        nonce,
305	    );
306	    let signature = signer(&envelope).map_err(|e| ConsentError::SigningFailed {
307	        message: e.to_string(),
308	    })?;
309	    let request = ApprovalRequest {
310	        did,
311	        signing_key: &device_key.key_id,
312	        request_id,
313	        decision,
314	        granted_scope,
315	        timestamp,
316	        nonce,
317	        signature: URL_SAFE_NO_PAD.encode(signature),
318	    };
319	
320	    let url = format!(
321	        "{}{}",
322	        pds_url.trim_end_matches('/'),
323	        crypto::OAUTH_CONSENT_APPROVE_PATH
324	    );
325	    let response = pds_client
326	        .client()
327	        .post(url)
328	        .json(&request)
329	        .send()
330	        .await
331	        .map_err(|e| ConsentError::TransportFailure {
332	            message: e.to_string(),
333	        })?;
334	    let status = response.status();
335	    if !status.is_success() {
336	        return Err(match status.as_u16() {
337	            400 => ConsentError::AlreadyResolved,
338	            401 | 403 => ConsentError::ApprovalRejected,
339	            404 => ConsentError::RequestNotFound,
340	            405 => ConsentError::UnsupportedHost,
341	            429 => ConsentError::RateLimited {
342	                retry_after: response
343	                    .headers()
344	                    .get(reqwest::header::RETRY_AFTER)
345	                    .and_then(|value| value.to_str().ok())
346	                    .map(str::to_string),
347	            },
348	            status => ConsentError::ServerFailure { status },
349	        });
350	    }
351	
352	    let response: ApprovalResponse =
353	        response
354	            .json()
355	            .await
356	            .map_err(|e| ConsentError::InvalidResponse {
357	                message: e.to_string(),
358	            })?;
359	    if response.did != did {
360	        return Err(ConsentError::DidMismatch);
361	    }
362	    // The recorded outcome must match the decision we signed: an approval reports `approved`, a
363	    // denial `denied`. Anything else is a malformed/unexpected response, not a success to display.
364	    let expected_status = if decision == crypto::OAUTH_CONSENT_DECISION_APPROVE {
365	        "approved"
366	    } else {
367	        "denied"
368	    };
369	    if response.status != expected_status {
370	        return Err(ConsentError::InvalidResponse {
371	            message: "server returned a decision status that did not match the submitted decision"
372	                .into(),
373	        });
374	    }
375	    Ok(ConsentDecision {
376	        status: response.status,
377	        did: did.into(),
378	    })
379	}
