1	// pattern: Imperative Shell (iOS-only Objective-C runtime bridge)
2	//
3	// How the device token reaches `notifications.rs`. iOS delivers it exactly once per launch, to
4	// two methods on the **application delegate** — there is no polling API, no
5	// `UIApplication.deviceToken` property, and no Tauri plugin for it. So this module installs
6	// those two methods on Tauri's delegate class at startup, before asking iOS to register.
7	//
8	// Everything here is compiled only for iOS (`lib.rs` gates the whole module), which also means
9	// it is compiled only by the `aarch64-apple-ios` cross-compile in the PR lane and exercised only
10	// on a device. Both consequences shape the code: the logic that *can* be tested lives in
11	// `notifications.rs` (hex encoding, change detection, the registration sequence), and what stays
12	// here is the smallest possible amount of runtime plumbing.
13	//
14	// # Why add methods rather than swizzle
15	//
16	// `class_addMethod` fails if the class already implements the selector, and that failure mode is
17	// the one we want: Tauri's delegate does not implement either method today, and if a future
18	// version starts to, silently replacing its implementation would be a far worse outcome than
19	// declining and logging. Nothing here ever calls `method_setImplementation` or
20	// `method_exchangeImplementations`, so no existing behaviour can be displaced.
21	//
22	// # Why a process-global handle
23	//
24	// An IMP is a bare C function pointer with no capture. The callback therefore reads the
25	// `AppHandle` from a `OnceLock` written during `setup` — the unit-of-global shape `IdentityStore`
26	// and `pds_capabilities` already use — rather than threading state it structurally cannot carry.
27	
28	use std::sync::OnceLock;
29	
30	use block2::RcBlock;
31	use objc2::rc::Retained;
32	use objc2::runtime::{AnyClass, AnyObject, Bool, Imp, Sel};
33	use objc2::{sel, MainThreadMarker};
34	use objc2_foundation::{NSData, NSError};
35	use objc2_ui_kit::UIApplication;
36	use objc2_user_notifications::{UNAuthorizationOptions, UNUserNotificationCenter};
37	use tauri::{AppHandle, Manager};
38	
39	/// The app handle the delegate callbacks resolve state through. Written once during `setup`.
40	static APP: OnceLock<AppHandle> = OnceLock::new();
41	
42	/// Ask the user for notification permission and, if granted, ask iOS for a device token.
43	///
44	/// Called from `setup`. Fire-and-forget by nature: the system prompt is answered whenever the
45	/// user answers it, the token arrives asynchronously afterwards, and the app is fully usable
46	/// throughout. Everything downstream treats "no token" as an ordinary state
47	/// (`AWAITING_APNS_TOKEN`), so a denied prompt costs banners and nothing else.
48	pub fn register_for_remote_notifications(app: &AppHandle) {
49	    if APP.set(app.clone()).is_err() {
50	        // `setup` runs once; a second call would mean the startup path grew a duplicate.
51	        tracing::warn!("APNs registration was requested twice; ignoring the second call");
52	        return;
53	    }
54	
55	    let Some(mtm) = MainThreadMarker::new() else {
56	        tracing::error!("APNs registration must run on the main thread; skipping");
57	        return;
58	    };
59	
60	    if !install_delegate_methods(mtm) {
61	        // Without the callbacks the token would arrive nowhere, so asking for one would only
62	        // spend a permission prompt the user gets nothing for.
63	        return;
64	    }
65	
66	    // Badge and sound alongside alerts: an encrypted payload still renders as a banner, and the
67	    // extension replaces its text in place — the presentation options are the same either way.
68	    let options = UNAuthorizationOptions::Alert
69	        | UNAuthorizationOptions::Sound
70	        | UNAuthorizationOptions::Badge;
71	    let handler = RcBlock::new(move |granted: Bool, error: *mut NSError| {
72	        if !error.is_null() {
73	            let description = unsafe { (*error).localizedDescription() }.to_string();
74	            tracing::warn!(error = %description, "notification authorization failed");
75	        }
76	        if !granted.as_bool() {
77	            tracing::info!("notification authorization was declined; not registering with APNs");
78	            return;
79	        }
80	        // `registerForRemoteNotifications` is main-thread-only and this block runs on an
81	        // arbitrary queue, so hop back before touching UIApplication.
82	        tauri::async_runtime::spawn(async {
83	            if let Some(app) = APP.get() {
84	                let _ = app.run_on_main_thread(|| {
85	                    if let Some(mtm) = MainThreadMarker::new() {
86	                        UIApplication::sharedApplication(mtm).registerForRemoteNotifications();
87	                    }
88	                });
89	            }
90	        });
91	    });
92	    UNUserNotificationCenter::currentNotificationCenter()
93	        .requestAuthorizationWithOptions_completionHandler(options, &handler);
94	}
95	
96	/// Install the two device-token callbacks on the live delegate's class.
97	///
98	/// Returns whether the token can now reach us — `false` when there is no delegate yet, or when
99	/// something already implements the selectors (see the module note on why that is a decline
100	/// rather than a replacement).
101	fn install_delegate_methods(mtm: MainThreadMarker) -> bool {
102	    let application = UIApplication::sharedApplication(mtm);
103	    let Some(delegate) = (unsafe { application.delegate() }) else {
104	        tracing::error!("no application delegate yet; cannot receive an APNs device token");
105	        return false;
106	    };
107	
108	    // The delegate is an object like any other, and its *class* is what the runtime dispatches
109	    // on — so that is where the methods go, not on the instance.
110	    let delegate_ptr: *const AnyObject = Retained::as_ptr(&delegate).cast();
111	    let class: *mut AnyClass = (unsafe { &*delegate_ptr }.class() as *const AnyClass).cast_mut();
112	
113	    // "v@:@@" — returns void, takes (self, _cmd, UIApplication, NSData | NSError).
114	    const SIGNATURE: &[u8] = b"v@:@@\0";
115	
116	    let registered = unsafe {
117	        objc2::ffi::class_addMethod(
118	            class,
119	            sel!(application:didRegisterForRemoteNotificationsWithDeviceToken:),
120	            std::mem::transmute::<DidRegisterFn, Imp>(did_register_with_token),
121	            SIGNATURE.as_ptr().cast(),
122	        )
123	    };
124	    if !registered.as_bool() {
125	        tracing::error!(
126	            "the application delegate already handles didRegisterForRemoteNotifications; \
127	             leaving it alone and skipping push registration"
128	        );
129	        return false;
130	    }
131	
132	    // Best-effort: without it a registration failure is silent, but the token path still works.
133	    let failure_registered = unsafe {
134	        objc2::ffi::class_addMethod(
135	            class,
136	            sel!(application:didFailToRegisterForRemoteNotificationsWithError:),
137	            std::mem::transmute::<DidFailFn, Imp>(did_fail_to_register),
138	            SIGNATURE.as_ptr().cast(),
139	        )
140	    };
141	    if !failure_registered.as_bool() {
142	        tracing::warn!("could not install the APNs registration-failure callback");
143	    }
144	
145	    true
146	}
147	
148	type DidRegisterFn = unsafe extern "C-unwind" fn(*mut AnyObject, Sel, *mut AnyObject, *mut NSData);
149	type DidFailFn = unsafe extern "C-unwind" fn(*mut AnyObject, Sel, *mut AnyObject, *mut NSError);
150	
151	/// `-application:didRegisterForRemoteNotificationsWithDeviceToken:`
152	///
153	/// iOS calls this on the main thread on every launch, whether or not the token changed, so the
154	/// work is gated on an actual change: re-registering every identity on every launch would spend
155	/// a round trip per identity to write rows that already say exactly this.
156	unsafe extern "C-unwind" fn did_register_with_token(
157	    _this: *mut AnyObject,
158	    _cmd: Sel,
159	    _application: *mut AnyObject,
160	    device_token: *mut NSData,
161	) {
162	    if device_token.is_null() {
163	        tracing::warn!("APNs delivered a null device token");
164	        return;
165	    }
166	    let token = crate::notifications::hex_encode_apns_token(&unsafe { &*device_token }.to_vec());
167	
168	    match crate::notifications::record_apns_token(&token) {
169	        Ok(false) => tracing::debug!("APNs device token is unchanged"),
170	        Ok(true) => {
171	            tracing::info!("APNs device token changed; re-registering every identity");
172	            let Some(app) = APP.get().cloned() else {
173	                return;
174	            };
175	            tauri::async_runtime::spawn(async move {
176	                let topic = app.config().identifier.clone();
177	                let state = app.state::<crate::oauth::AppState>();
178	                crate::notifications::re_register_every_identity(&topic, state.pds_client()).await;
179	            });
180	        }
181	        Err(e) => tracing::error!(error = ?e, "could not store the APNs device token"),
182	    }
183	}
184	
185	/// `-application:didFailToRegisterForRemoteNotificationsWithError:`
186	///
187	/// Logged, never escalated. The ordinary causes are a simulator with no push support and a
188	/// device with no network at launch, both of which resolve on their own; the stored state stays
189	/// "no token", which every caller already handles.
190	unsafe extern "C-unwind" fn did_fail_to_register(
191	    _this: *mut AnyObject,
192	    _cmd: Sel,
193	    _application: *mut AnyObject,
194	    error: *mut NSError,
195	) {
196	    let description = if error.is_null() {
197	        "unknown error".to_string()
198	    } else {
199	        unsafe { (*error).localizedDescription() }.to_string()
200	    };
201	    tracing::warn!(error = %description, "APNs registration failed");
202	}
