164	/// Register `device_public_key` through the real HTTP route, then wait for the background
165	/// worker to complete the relay round trip.
166	async fn register_device(state: &AppState, device_public_key: &str) {
167	    let response = crate::app::app(state.clone())
168	        .oneshot(
169	            Request::post("/v1/notifications/register")
170	                .header("authorization", format!("Bearer {}", access_token(state)))
171	                .header("content-type", "application/json")
172	                .body(Body::from(
173	                    json!({
174	                        "deviceUuid": DEVICE_UUID,
175	                        "notificationPublicKey": device_public_key,
176	                        "apnsToken": "deadbeef0123456789",
177	                        "apnsTopic": "org.obsign.identitywallet",
178	                    })
179	                    .to_string(),
180	                ))
181	                .unwrap(),
182	        )
183	        .await
184	        .expect("register response");
185	    assert_eq!(response.status(), StatusCode::OK);
186	
187	    // The route returns before the relay knows anything — that is the deliberate design.
188	    // Wait for the handle rather than sleeping a fixed amount, so the test is not timing-luck.
189	    let handle = await_condition("a relay push handle", || async {
190	        store::list_registrations(&state.db, ACCOUNT_DID)
191	            .await
192	            .ok()
193	            .and_then(|rows| rows.into_iter().next())
194	            .and_then(|row| row.push_handle)
195	    })
196	    .await;
197	    assert!(!handle.is_empty());
198	}
