200	/// Poll `probe` until it yields a value, or fail the test. Condition-based rather than a
201	/// fixed sleep: the worker is asynchronous, and a sleep would either be flaky or slow.
202	async fn await_condition<T, F, Fut>(what: &str, mut probe: F) -> T
203	where
204	    F: FnMut() -> Fut,
205	    Fut: std::future::Future<Output = Option<T>>,
206	{
207	    let deadline = tokio::time::Instant::now() + Duration::from_secs(20);
208	    loop {
209	        if let Some(value) = probe().await {
210	            return value;
211	        }
212	        assert!(
213	            tokio::time::Instant::now() < deadline,
214	            "timed out waiting for {what}"
215	        );
216	        tokio::time::sleep(Duration::from_millis(25)).await;
217	    }
218	}
