232	/// The full happy path: register, seal, push — and the device opens it.
233	#[tokio::test]
234	async fn a_notification_travels_from_custos_through_the_relay_to_a_device_that_opens_it() {
235	    let apple = MockServer::start().await;
236	    Mock::given(method("POST"))
237	        .respond_with(ResponseTemplate::new(200))
238	        .mount(&apple)
239	        .await;
240	
241	    let (relay_endpoint, _relay, _keydir) = start_relay(&apple.uri()).await;
242	    let relay_addr =
243	        EndpointAddr::new(relay_endpoint.id()).with_ip_addr(relay_endpoint.bound_sockets()[0]);
244	    let (state, dialer) = start_pds(relay_addr).await;
245	
246	    // The "device": a keypair the app would generate and register.
247	    let device = crypto::generate_p256_keypair().expect("device keypair");
248	    register_device(&state, &device.key_id.0).await;
249	
250	    let (kid, sender_public_key) = published_sender_key(&state).await;
251	
252	    crate::notifications::notify_device(
253	        &state,
254	        ACCOUNT_DID,
255	        crate::notifications::NotificationPayload::new(
256	            "agent_claim_pending",
257	            "Confirm agent access",
258	            "An agent is waiting for you to approve it.",
259	        )
260	        .with_data(json!({ "claimAttemptId": "clm_e2e" })),
261	    )
262	    .await;
263	
264	    // Apple's first request is the registration-time nothing; the push is the one with a body
265	    // carrying our envelope. Wait for it rather than assuming ordering.
266	    // Keep the raw byte length alongside the parsed value: the padding assertion below has to
267	    // measure what actually crossed the wire, since parse-and-reserialize could normalize away
268	    // the very size drift it is there to catch.
269	    let (serialized_len, body) = await_condition("the pushed APNs body", || async {
270	        apple
271	            .received_requests()
272	            .await
273	            .unwrap_or_default()
274	            .into_iter()
275	            .find_map(|req| {
276	                serde_json::from_slice::<serde_json::Value>(&req.body)
277	                    .ok()
278	                    .map(|parsed| (req.body.len(), parsed))
279	            })
280	    })
281	    .await;
282	
283	    // What Apple (and the relay) can see: a fixed, content-free placeholder. The actual
284	    // notification is opaque to both.
285	    assert_eq!(body["aps"]["alert"]["title"], "Custos");
286	    assert_eq!(body["aps"]["alert"]["body"], "Encrypted notification");
287	    assert_eq!(body["aps"]["mutable-content"], 1);
288	    assert_eq!(body["ezpds"]["v"], 1);
289	    assert_eq!(
290	        body["ezpds"]["kid"], kid,
291	        "the envelope must name the key the instance published"
292	    );
293	
294	    // The body Apple received must sit on a padding bucket — the assertion that catches the two
295	    // crates disagreeing about the envelope's shape, since Custos computed the pad against its
296	    // own model of these very bytes. The one-byte tolerance is not slack: base64's four-chars-
297	    // per-three-bytes step makes some bucket targets unreachable, so `plaintext_pad_len`
298	    // documents (and its own tests pin) landing on the bucket or one byte under it.
299	    assert!(
300	        crypto::PADDING_BUCKETS.contains(&serialized_len)
301	            || crypto::PADDING_BUCKETS.contains(&(serialized_len + 1)),
302	        "body was {serialized_len} bytes, not on a padding bucket {:?}",
303	        crypto::PADDING_BUCKETS
304	    );
305	
306	    // Now the device's half: open the payload, which also *verifies the sender*. HPKE
307	    // mode_auth means a successful open is proof the instance's sender key sealed it — the
308	    // relay could not have authored this.
309	    let decode = |field: &str| {
310	        data_encoding::BASE64URL_NOPAD
311	            .decode(body["ezpds"][field].as_str().expect("string").as_bytes())
312	            .expect("base64url")
313	    };
314	    let plaintext = crypto::open_notification(
315	        &device.private_key_bytes,
316	        &sender_public_key,
317	        &decode("enc"),
318	        &decode("ct"),
319	    )
320	    .expect("the device must be able to open a payload sealed to it");
321	
322	    let opened: serde_json::Value = serde_json::from_slice(&plaintext).expect("payload JSON");
323	    assert_eq!(opened["type"], "agent_claim_pending");
324	    assert_eq!(opened["title"], "Confirm agent access");
325	    assert_eq!(opened["data"]["claimAttemptId"], "clm_e2e");
326	
327	    // An impostor holding the same ciphertext cannot make it verify as ours.
328	    let impostor = crypto::generate_p256_keypair().expect("impostor keypair");
329	    let impostor_public = crypto::public_key_for_secret(&impostor.private_key_bytes).unwrap();
330	    assert!(
331	        crypto::open_notification(
332	            &device.private_key_bytes,
333	            &impostor_public,
334	            &decode("enc"),
335	            &decode("ct"),
336	        )
337	        .is_err(),
338	        "mode_auth must refuse a payload attributed to the wrong sender"
339	    );
340	
341	    dialer.close().await;
342	    relay_endpoint.close().await;
343	}
